export const T_BALL = {
  /** m/s^2 */
  gravity: 9.81,
  /** Quadratic air drag: a = -k * |v| * v, 1/m. (rho * Cd * A / 2m ~ 1.2*0.25*0.038/0.86) */
  dragK: 0.0133,
  /** Magnus lift: a = magnusK * (spin x v), dimensionless per (rad/s * m/s). */
  magnusK: 0.0042,
  /** Spin decay per second in air (fraction lost per s). */
  spinDecayAir: 0.25,
  /** Vertical restitution on grass (bounce height ~halves: sqrt(0.5) ~ 0.7). */
  restitution: 0.68,
  /** Tangential friction on bounce (fraction of horizontal speed lost per bounce). [QF-10] 0.12 -> 0.18: long balls
   *  skipped on 37-47 m after their first bounce (now 31-41 m); 0.18 is as far as SIM-08's dinked-pass model keeps its
   *  arrival speed within 0.6 m/s of the plan (0.19-0.2 miss on a few short dinks; docs/TUNING.md). */
  bounceFriction: 0.18,
  /** Rolling resistance deceleration on grass, m/s^2. */
  rollDecel: 2.2,
  /** Extra speed-proportional rolling damping, 1/s. */
  rollDamping: 0.12,
  /** Below this vertical speed (m/s) at ground contact the ball starts rolling. */
  rollThresholdVy: 0.6,
  /** Ball comes to rest below this speed (m/s). */
  restSpeed: 0.05,
  /** Max substep length (m) for swept collisions: substeps = ceil(|v|*DT / maxStep). */
  maxStep: 0.08,
  /** Restitution off posts/bar. */
  postRestitution: 0.55,
  /** Net absorbs this fraction of speed per tick inside the net volume. */
  netDamping: 0.35,
  /** Side netting / roof deflection restitution from outside. */
  netOutsideRestitution: 0.15,
  /** Advertising boards restitution. */
  boardRestitution: 0.3,
  /** Max ball speed m/s (clamp). */
  maxSpeed: 40,
} as const;

